type OnRound2ToolHandler = (lastMessage: SendMessageParams['messages'][number]) => void;

function createMultiRoundToolProvider(onRound2: OnRound2ToolHandler, finalText: string): AIProvider {
  let round = 0;
  return {
    async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
      round += 1;
      if (round === 1) {
        yield {type: 'tool_use', toolCall: {id: 'call-1', name: 'get_weather', input: {}}};
        yield {type: 'stop', stopReason: 'tool_use'};
        return;
      }
      if (round !== 2) {
        yield {type: 'text', text: finalText};
        yield {type: 'stop', stopReason: 'end_turn'};
        return;
      }
      const lastMessage = params.messages[params.messages.length - 1];
      onRound2(lastMessage);
      yield {type: 'tool_use', toolCall: {id: 'call-2', name: 'get_weather', input: {location: 'Paris'}}};
      yield {type: 'stop', stopReason: 'tool_use'};
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

